export interface SetupPackage {
  id: string;
  slug: string;
  name: string;
  emoji: string;
  shortDescription: string;
  fullDescription: string;
  price: number;
  cakeIncluded: boolean; // true for Setup 1-3, false for Setup 4-8 (extra cost)
  features: string[];
  perfectFor: string[];
  thumbnail: string;
  images: string[];
}

export interface ServiceCategory {
  slug: string;
  name: string;
  emoji: string;
  description: string;
  metaTitle: string;
  metaDescription: string;
  keywords: ServiceKeyword[];
}

export interface ServiceKeyword {
  slug: string;
  title: string;
  h1: string;
  metaTitle: string;
  metaDescription: string;
  // NEW: Unique content fields for each page
  uniqueContent?: {
    heroSubtitle: string;
    introduction: string;
    whyChooseUs: string[];
    features: string[];
    process: { step: string; description: string }[];
    faqs: { question: string; answer: string }[];
    testimonial: { name: string; text: string; rating: number };
    closingText: string;
  };
}

export interface AreaConfig {
  slug: string;
  name: string;
  // NEW: Unique content fields for each area page
  uniqueContent?: {
    heroSubtitle: string;
    introduction: string;
    aboutArea: string;
    whyChooseUs: string[];
    servicesDescription: string;
    locationAdvantage: string;
    faqs: { question: string; answer: string }[];
    testimonial: { name: string; location: string; text: string; rating: number };
    nearbyLandmarks: string[];
    closingText: string;
  };
}

